<script setup>
import {ref,watch} from 'vue';import api from '../../services/api';
const props=defineProps({clientId:Number});const state=ref(null),requests=ref([]),error=ref(''),busy=ref(false),reviewed=ref(false),evidence=ref(''),basis=ref('adult_self');let sequence=0;
async function load(){const run=++sequence;state.value=null;requests.value=[];error.value='';reviewed.value=false;evidence.value='';try{const [a,b]=await Promise.all([api.get(`/dependent-portal/staff/${props.clientId}/independence`,{skipGlobalLoading:true}),api.get(`/dependent-portal/staff/${props.clientId}/support-requests`,{skipGlobalLoading:true})]);if(run!==sequence)return;state.value=a.data;requests.value=b.data.requests;basis.value=a.data.ageReviewRequired?'verified_emancipation':'adult_self';}catch(e){if(run===sequence&&e.response?.status!==403)error.value='Independence review could not be loaded.';}}
async function review(approve){busy.value=true;error.value='';try{await api.post(`/dependent-portal/staff/${props.clientId}/independence`,{version:state.value.version,approve,basis:basis.value,evidence:evidence.value,reviewed:reviewed.value});await load();}catch(e){error.value=e.response?.data?.error?.message||'Review could not be saved.';}finally{busy.value=false;}}
async function resolve(r){busy.value=true;try{await api.post(`/dependent-portal/staff/${props.clientId}/support-requests/${r.id}/resolve`);await load();}catch(e){error.value=e.response?.data?.error?.message||'This request could not be updated.';}finally{busy.value=false;}}
watch(()=>props.clientId,load,{immediate:true});
</script>
<template><section v-if="state||error" class="independence-review"><h3>Access &amp; independence</h3><p v-if="error" role="alert">{{error}}</p><template v-if="state"><p>{{state.status==='not_requested'?'No independence review requested. The client can request a review from their personal portal.':state.status==='active'?'Client-controlled account. Former family access is disabled.':state.status==='requested'?'The client has requested an independence review.':'Previous request declined; follow up with the client.'}}</p><button @click="load" :disabled="busy">Refresh</button>
<ul v-if="state.choices?.length"><li v-for="c in state.choices" :key="`${c.helperUserId}:${c.agencyId}`">{{state.helpers.find(p=>Number(p.id)===Number(c.helperUserId))?.name}} · {{state.agencies.find(a=>Number(a.id)===Number(c.agencyId))?.name}}: {{c.scopes.length?c.scopes.join(', '):'No assistance access'}}</li></ul>
<form v-if="state.status==='requested'" @submit.prevent="review(true)"><p>Approval applies across this client’s agencies. It ends former guardian portal access, clinical grants, shared conversation participation, and additional-contact reminders. Only the client’s selected assistance remains. It does not delete records or transfer debt.</p><label>Authority<select v-model="basis"><option value="adult_self">Adult client directing their own account</option><option value="verified_emancipation">Legally verified emancipation</option></select></label><label>Authority review and evidence reference<textarea v-model="evidence" minlength="20" maxlength="8000" rows="4" required placeholder="Record identity verification, applicable authority, evidence reviewed and any restrictions." /></label><label class="check"><input v-model="reviewed" type="checkbox" required />I verified the client’s authority and identity, reviewed any court orders or representatives and confidential communication restrictions, and coordinated all agencies. There is no continuing representative authority that this transition would improperly remove.</label><p>Service-specific minor consent is handled through clinical access controls; it does not establish general emancipation.</p><button :disabled="busy||!reviewed||evidence.trim().length<20">Approve this exact request</button> <button type="button" :disabled="busy||!evidence.trim()" @click="review(false)">Decline and follow up</button></form>
<h4 v-if="requests.length">Assistance requests</h4><article v-for="r in requests" :key="r.id"><strong>{{r.helperName}} · {{r.agencyName}} · {{r.scope}} · {{r.status}}</strong><p class="message">{{r.message}}</p><p v-if="r.status==='pending'">Review the current permission and complete any appropriate change in the client chart or schedule. Account credentials are excluded.</p><button v-if="r.status==='pending'" :disabled="busy" @click="resolve(r)">Mark handled</button></article></template></section></template>
<style scoped>.independence-review{padding:20px;background:#f6f9fc;border:1px solid #ccd9e5;border-radius:12px;margin:18px 0}.independence-review label{display:grid;gap:8px;margin:14px 0}.independence-review .check{display:flex;align-items:flex-start}.independence-review textarea,.independence-review select{font:inherit;padding:10px;border:1px solid #bacddd;border-radius:8px;width:100%;box-sizing:border-box}.independence-review button{font:inherit;padding:10px 14px}.independence-review p,.independence-review li{line-height:1.6}.independence-review ul{padding-left:24px}.message{white-space:pre-wrap}.independence-review article{padding:16px 0;border-top:1px solid #ccd9e5}[role=alert]{color:#a12424}</style>
